        # Mocking the RDD and context for testing
        class MockRDD:
            def __init__(self, data):
                self.data = data
                self.partitions = [data[i:i + 1] for i in range(len(data))]

            def getNumPartitions(self):
                return len(self.partitions)

            def context(self):
